import { defineTool as defineTool12 } from "npm:@lovable.dev/mcp-js@0.20.0";
import { z as z9 } from "npm:zod@^4.4.3";

// src/lib/mcp/importing.ts
function itemsWithOrder(items, startOrder) {
  const start = Number.isFinite(Number(startOrder)) ? Math.max(0, Math.round(Number(startOrder))) : void 0;
  return items.map((it, i) => ({
    title: it.title,
    content: it.content,
    ...start === void 0 ? {} : { order: start + i }
  }));
}
async function callImport(ctx, payload) {
  return callEdgeFunction(ctx, "import-content", payload);
}
async function resolveDraft(ctx, kind, projectId) {
  const supa = supabaseForUser(ctx);
  const type = kind === "book" ? "ebook" : "course_pack";
  let q = supa.from("ai_content_projects").select("id, title, organization_id, project_type, updated_at").order("updated_at", { ascending: false }).limit(1);
  if (projectId) {
    q = supa.from("ai_content_projects").select("id, title, organization_id, project_type, updated_at").eq("id", projectId).limit(1);
  } else {
    q = q.eq("project_type", type);
  }
  const { data, error } = await q;
  if (error) return { error: error.message };
  const row = (data ?? [])[0];
  if (!row) {
    return {
      error: projectId ? `No draft found with id ${projectId}.` : `No ${kind} draft found. Create it first with import_${kind}_from_content.`
    };
  }
  return { project_id: row.id, org_id: row.organization_id, title: row.title };
}
function importReply(data, opts) {
  const unit = opts.kind === "book" ? "chapters" : "lessons";
  const link = data?.draft_url || `${APP_BASE_URL}/ecrire`;
  const nextTool = opts.kind === "book" ? "add_book_chapters" : "add_course_lessons";
  const count = Number(data?.item_count || 0);
  const expected = Number(data?.expected_item_count || 0);
  const remaining = expected ? Math.max(0, expected - count) : 0;
  const complete = expected ? remaining === 0 : void 0;
  const lines = [
    link,
    "",
    expected ? `${count} of ${expected} ${unit} are in the draft (${data?.tier_label}).` : opts.appended ? `Added \u2014 the draft now holds ${count} ${unit} (${data?.tier_label}).` : `Draft ready \u2014 ${count} ${unit}, ${data?.tier_label}.`,
    "Imported verbatim \u2014 SiteViral did not rewrite your text."
  ];
  if (data?.cover_generated) lines.push("Cover generated.");
  if (Number(data?.images_generated) > 0) lines.push(`${data.images_generated} illustration(s) generated.`);
  if (Number(data?.images_missing) > 0) {
    lines.push(
      `The remaining ${data.images_missing} illustration(s) are being generated right now in the background \u2014 SiteViral finishes them automatically, they will all be in the draft in a few minutes. Tell the user the illustrations are finishing, and do NOT call finish_draft_visuals unless the user says some are still missing later.`
    );
  }
  if (data?.visuals_stopped_for_credits) {
    lines.push(
      `Some visuals were not generated: not enough credits on the SiteViral account. Add credits at ${APP_BASE_URL}/credits, then ask for the visuals again.`
    );
  }
  lines.push(
    "",
    "IDS FOR THE NEXT BATCH \u2014 copy these exact values, never invent them:",
    `project_id: ${data?.project_id}`,
    `org_id: ${data?.org_id}`
  );
  if (complete === false) {
    lines.push(
      "",
      `NOT FINISHED \u2014 ${remaining} ${unit} are still missing.`,
      `Call ${nextTool} NOW with the next batch (up to 12 ${unit} per call), project_id above and start_order: ${count}.`,
      "Do NOT tell the user the import is done, and do NOT stop, until this reply says the draft is complete."
    );
  } else {
    lines.push(
      `If more ${unit} remain, send them with ${nextTool} using those ids and start_order: ${count}.`,
      `If you lost the ids, call ${nextTool} without them: SiteViral appends to this same draft.`
    );
    if (complete === true) lines.push(`All ${expected} ${unit} are in the draft \u2014 the import is complete.`);
  }
  lines.push(
    "",
    "Show this draft link to the user as a clickable link in your next message \u2014 it opens the exact draft.",
    "Next: open the draft to review, price and publish it."
  );
  return textResult(lines.join("\n"), {
    draft_url: link,
    project_id: data?.project_id,
    org_id: data?.org_id,
    item_count: count,
    expected_item_count: expected || null,
    remaining: expected ? remaining : null,
    complete: complete ?? null,
    next_tool: nextTool,
    next_start_order: count,
    tier: data?.tier,
    verbatim: true,
    cover_generated: !!data?.cover_generated,
    images_generated: Number(data?.images_generated || 0),
    images_missing: Number(data?.images_missing || 0)
  });
}

